# פרק 3 (שלד אוטומטי מהתוכן הקיים; להעמקה)
N=3
TITLE='התרשלות והפרת החובה'
SUM=[' <p>היסוד השני: לאחר שנמצאה חובת זהירות — האם המזיק <strong>הפר</strong> אותה, כלומר התרשל.</p> <h3>3.1 סטנדרט "האדם הסביר" — סעיף 35</h3> <p>התרשלות היא סטייה מרמת הזהירות של ה<strong>אדם הסביר והנבון</strong> באותן נסיבות — מבחן <strong>אובייקטיבי</strong>. בעל מקצוע נמדד לפי "אדם סביר וכשיר באותו משלח-יד" (רופא לפי רופא סביר), ברמת זהירות מוגברת.</p> <h3>3.2 איזון עלות-תועלת (נוסחת הנד)</h3> <p>הקביעה אם ננקטה זהירות סבירה כרוכה באיזון: <strong>הסתברות הנזק × חומרתו</strong> מול <strong>עלות אמצעי המניעה</strong>. כאשר עלות המניעה נמוכה מתוחלת הנזק — אי-נקיטתה היא התרשלות (נוסחת Learned Hand).</p> <h3>3.3 "הדבר מדבר בעדו" — סעיף 41</h3> <p>בנסיבות מסוימות (הנזק אינו מתיישב עם היעדר התרשלות, והנכס בשליטת הנתבע) — <strong>נטל ההוכחה עובר לנתבע</strong> לשלול התרשלות (res ipsa loquitur).</p> <h3>3.4 נקודות מפתח למבחן</h3> <ul><li>מבחן אובייקטיבי — האדם הסביר (ס׳ 35); סטנדרט מקצועי מוגבר.</li><li>נוסחת הנד — איזון תוחלת הנזק מול עלות המניעה.</li><li>ס׳ 41 — היפוך נטל ההוכחה.</li></ul> <p style="margin-top:18px;padding-top:9px;border-top:1px solid var(--line,#3a342a);font-size:11px;color:var(--muted,#8a8475)">© כל הזכויות שמורות ל<b>אילן פרץ</b> · אין להעתיק, לשכפל או להפיץ ללא רשות בכתב.</p>']
CASES=[("ס' 35 לפקודת הנזיקין — מבחן האדם הסביר", '', 'התרשלות = סטייה מרמת הזהירות של אדם סביר ונבון (ובמשלח-יד — בעל מקצוע סביר וכשיר) באותן נסיבות; מבחן אובייקטיבי.'), ('נוסחת Learned Hand — איזון עלות-תועלת', '', 'השוואת עלות אמצעי המניעה לתוחלת הנזק (הסתברות × חומרה) לקביעת סבירות הזהירות.'), ('ס\' 41 — "הדבר מדבר בעדו"', '', 'בנסיבות מתאימות מועבר נטל ההוכחה אל הנתבע לשלול התרשלות (res ipsa loquitur).'), ('ע״א 5604/94 חמד נ׳ מדינת ישראל, פ״ד נח(2) 498 (2004)', 'ילד נפגע מכדור גומי שירה שוטר משמר הגבול במהלך מרדף לילי אחר מפרי סדר במחנה פליטים, בזמן שהשוטרים עצמם לא היו בסכנה.', 'הנשיא ברק ערך איזון בין האינטרס של הניזוק, האינטרס של המזיק והאינטרס הציבורי בהשלטת הסדר, וקבע שירי כדורי גומי בנסיבות כאלה (ריצה, חושך, בלי סכנה לשוטרים) אינו אמצעי סביר ומידתי. השופט ריבלין הציע לראות בנוסחת הנד "מסגרת רעיונית" שבית המשפט יוצק לתוכה ערכים, ולא רק חשבון של יעילות כלכלית.'), ('ע״א 343/74 גרובנר נ׳ עיריית חיפה, פ״ד ל(1) 141', 'אישה נפגעה מרוכב אופניים בגן ציבורי בחיפה, וטענה שהעירייה התרשלה כשלא אכפה את האיסור לרכוב בגן.', 'התביעה נדחתה. כדי למנוע את הנזק הייתה העירייה צריכה להציב פקחים בגנים, והעלות הגבוהה הייתה באה על חשבון צרכים ציבוריים אחרים, בעוד הסיכון נמוך יחסית. גם לערך החברתי של גנים פתוחים לציבור ניתן משקל. האיזון הראוי הוא פיקוח חלקי, ולכן לא נמצאה התרשלות.'), ('ע״א 1678/01 מדינת ישראל נ׳ וייס, פ״ד נח(5) 167 (2004)', 'משפחה סבלה הטרדות חוזרות ונשנות מצד שכנים, ותלונותיה למשטרה לא טופלו כראוי לאורך זמן.', 'השופטת דורנר מנתה את שיקולי ההתרשלות: הסתברות הנזק, חומרתו, עלות המניעה והאינטרס הציבורי בפעילות. ככל שההסתברות והחומרה גבוהות יותר, העלות נמוכה יותר והערך החברתי נמוך יותר, כך גוברת הנטייה להטיל אחריות. המשטרה, שהיו בידיה אמצעים פשוטים לטפל בתלונות, נמצאה רשלנית. הודגש גם שהערך החברתי אינו כלכלי בלבד.'), ('ע״א 4486/11 פלוני נ׳ פלוני (15.7.2013)', 'פסק דין של השופט עמית בתביעת רשלנות, שבו נדונו אמות המידה לבחינת ההתרשלות (סבירות החלטות שהתקבלו בזמן אמת ונוסחת הנד) ומבחני הקשר הסיבתי המשפטי.', 'הודגש שיש לבחון את ההתנהגות לפי מה שהיה ידוע בעת המעשה, ולהתחשב בצורך להחליט מהר בלי לבחון לעומק את כל החלופות. העובדה שנבחרה חלופה שבבחינה רגועה לא הייתה נבחרת אינה מוכיחה כשלעצמה התרשלות. עוד נקבע שנוסחת הנד אינה מבטאת רק יעילות כלכלית, ושאפשר לשלב בה תפיסות שונות של צדק.'), ('ד״נ 4/69 נוימן נ׳ כהן, פ״ד כד(2) 229', 'דיון נוסף בשאלה מה טיבו של הנטל שעובר לנתבע כשמתקיימים תנאי ס׳ 41, "הדבר מעיד על עצמו".', 'נקבע, ברוב דעות (הנשיא אגרנט), שעובר נטל השכנוע, ולא רק נטל הבאת הראיות. אם בסוף המשפט הראיות שקולות, הנתבע מפסיד. הנימוק נשען גם על הנוסח האנגלי המקורי של הסעיף. דעת המיעוט (השופט לנדוי) הדגישה שהשאלה היא מה ידוע לבית המשפט, ועמדה זו השפיעה על הפסיקה המאוחרת.'), ('ע״א 8151/98 שטרנברג נ׳ צ׳צ׳יק, פ״ד נו(1) 539 (2001)', 'מטופלת עברה ניתוח להחלפת מפרק בברך ונפגעה בעצב באזור הניתוח, והתעוררו שאלות של הוכחת ההתרשלות ושל חסר ברישום.', 'השופט ריבלין קבע שתנאי אי־הידיעה בס׳ 41 נבחן לפי מה שהתברר עד תום המשפט, ושתנאי ההסתברות דורש הסתברות כללית לרשלנות בסוג כזה של מקרים. בעניין הנזק הראייתי נקבע שעובר נטל השכנוע, ושהיקף ההעברה נגזר מהיקף החסר הראייתי שגרם הנתבע.')]
QS=[{'q': 'מדוע אומרים שרשלנות היא "אשמה חברתית" ולא "אשמה מוסרית"?', 'o': ['כי צריך להוכיח כוונה רעה', 'כי הסטנדרט אובייקטיבי, ומי שעשה כמיטב יכולתו עדיין יכול להיות רשלן אם לא עמד ברמת האדם הסביר', 'כי רק החברה רשאית לתבוע ברשלנות', 'כי רשלנות היא תמיד גם עבירה פלילית'], 'c': 1, 'e': 'נכון. משווים את המזיק לסטנדרט שהחברה מצפה לו, ולא ליכולת האישית שלו או לפגם מוסרי.'}, {'q': 'לפי נוסחת הנד, מתי מזיק התרשל?', 'o': ['בכל פעם שנגרם נזק', 'כשעלות אמצעי המניעה (B) נמוכה מתוחלת הנזק (P×L), והוא לא נקט אותם', 'כשעלות המניעה גבוהה מתוחלת הנזק', 'כשההסתברות לנזק עולה על 50%'], 'c': 1, 'e': 'נכון. כשאמצעי זהירות זולים יחסית לנזק הצפוי ולא ננקטו, הדבר מעיד על התרשלות.'}, {'q': 'מה הייתה תרומת השופט ריבלין בעניין חמד לגבי נוסחת הנד?', 'o': ['הציע לראות בה מסגרת רעיונית שבית המשפט יוצק לתוכה ערכים כמו צדק והגינות, ולא רק חשבון כלכלי', 'ביטל את הנוסחה', 'קבע שהנוסחה חלה רק על רשויות', 'קבע שהנוסחה מחייבת חישוב מספרי מדויק בכל תיק'], 'c': 0, 'e': 'נכון. "זוהי מסגרת רעיונית אשר משמשת את בית-המשפט ככלי של היגיון". פגיעה בצדק היא עלות, וצדק מתקן הוא תועלת.'}, {'q': 'איזה שיקול מנקודת המבט של הציבור משפיע על קביעת ההתרשלות?', 'o': ['זהות עורך הדין של המזיק', 'מספר העדים באירוע', 'מצבו הכלכלי של הניזוק', 'הערך החברתי של הפעילות המזיקה'], 'c': 3, 'e': 'נכון. לפעילות בעלת ערך חברתי רב, כמו ביטחון, שיטור או רפואה, ניתן משקל שעשוי להצדיק סיכון מסוים (וייס, חמד, מלכיה).'}, {'q': 'בעל מקצוע טוען שפעל לפי הנוהג המקובל בתחומו. מה המשמעות המשפטית?', 'o': ['זו ראיה חזקה לסבירות, אבל ביהמ״ש רשאי לקבוע שהנוהג עצמו אינו סביר', 'זו הגנה מוחלטת', 'הטענה רלוונטית רק בפלילים', 'אין לכך כל משקל'], 'c': 0, 'e': 'נכון. הנוהג המקובל הוא נקודת התייחסות חשובה, אבל נוהג שחושף לסיכון מיותר שקל למנוע יכול להיחשב בעצמו רשלני.'}, {'q': 'מה מעביר ס׳ 41 לנתבע לפי הלכת נוימן נ׳ כהן?', 'o': ['רק את נטל הבאת הראיות', 'את חובת התשלום, בלי אפשרות להתגונן', 'את נטל השכנוע, כך שאם הראיות שקולות הנתבע מפסיד', 'שום דבר. ס׳ 41 רק מאפשר להגיש ראיות נוספות'], 'c': 2, 'e': 'נכון. זו ההלכה, והיא מיטיבה מאוד עם התובע במצבי "ספק שקול".'}, {'q': 'נהג חדש, עם רישיון בן חודש, גרם לתאונה בפנייה חדה שנהג מנוסה היה מבצע בבטחה. הוא טוען שעשה כמיטב יכולתו. מה הדין?', 'o': ['הוא נבחן לפי סטנדרט אובייקטיבי של נהג סביר, וחוסר הניסיון שלו אינו הגנה', 'הוא פטור, כי נבחן לפי יכולתו כנהג חדש', 'הוא פטור כי עבר מבחן נהיגה', 'הוא חב רק אם נהג במהירות מופרזת'], 'c': 0, 'e': 'נכון. אחרת הנפגעים היו נושאים בסיכון שנובע מחוסר הניסיון של הנהג. "כמיטב יכולתו" אינה הגנה.'}, {'q': 'נהג סטה בבת אחת כדי לא לדרוס כלב שקפץ לכביש, עלה על אי תנועה, ונוסעת ברכב נפצעה. הוא טוען שזו תגובה אינסטינקטיבית. מה הדין?', 'o': ['הנהג פטור, כי הכלב הוא הגורם המכריע', 'הנהג חב תמיד, כי הנוסעת נפגעה', 'מצב חירום מתחשבים בו, אבל גם בתנאי דוחק בוחנים מה היה עושה נהג סביר. יש תגובה אינסטינקטיבית שאינה סבירה', 'תגובה אינסטינקטיבית תמיד פוטרת'], 'c': 2, 'e': 'נכון. בפסיקה נקבע במקרה כזה שגם תגובה אינסטינקטיבית נבחנת לפי סבירות, וסטייה חדה שמסכנת נוסעים כדי לא לפגוע בכלב עשויה להיות בלתי סבירה.'}, {'q': 'עירייה נתבעה כי לא הציבה פקח קבוע בכל גן שעשועים כדי למנוע רכיבה מסוכנת על אופניים. לפי הלכת גרובנר, מה הסיכוי שתימצא רשלנית?', 'o': ['גבוה, כי רשות חייבת למנוע כל נזק בשטחה', 'אפסי, כי לעיריות אין חובת זהירות', 'נמוך. עלות הצבת פקחים בכל הגנים גבוהה מאוד ביחס לסיכון, ולגנים הפתוחים יש ערך חברתי. פיקוח חלקי הוא האיזון הראוי', 'גבוה, כי הנזק היה צפוי'], 'c': 2, 'e': 'נכון. זה בדיוק הניתוח בגרובנר, ששילב את נוסחת הנד עם הערך החברתי של הפעילות ועם המשאבים המוגבלים.'}, {'q': 'סככה רעועה בחוף הים קרסה על אדם. העירייה ידעה על מצבה, ויכלה לפחות להזהיר את בעלי השטח או להציב שלט. היא טוענת באופן כללי למחסור תקציבי. לפי הלכת זוהר, מה הדין?', 'o': ['העירייה פטורה כי הסככה בבעלות פרטית בחלקה', 'טענת מחסור תקציבי צריכה להיות מוכחת, למשל בהצגת סדרי עדיפויות. כשאמצעי המניעה זול והנזק האפשרי חמור, סביר שתימצא התרשלות', 'טענת התקציב פוטרת מעצמה', 'העירייה חבה רק אם היא הבעלים של הסככה'], 'c': 1, 'e': 'נכון. ברק קבע שלא הובאה ראיה שהטיפול נדחה בגלל סדרי עדיפויות, ושעלות האזהרה נמוכה.'}, {'q': 'שוטר ירה כדורי גומי במהלך מרדף לילי אחר מפרי סדר, כשלא נשקפה לו סכנה, ופגע בעובר אורח. לפי הלכת חמד, מה הניתוח?', 'o': ['כל פעולה של כוחות הביטחון סבירה מעצם טבעה', 'המדינה חבה רק אם השוטר התכוון לפגוע', 'לפעולה ערך חברתי רב, אבל האמצעי צריך להיות מידתי. ירי לא מדויק בחושך ובריצה, בלי סכנה לשוטרים, אינו סביר', 'השוטר פטור כי פעל במסגרת תפקידו'], 'c': 2, 'e': 'נכון. כך נפסק בחמד. לעומת זאת, ירי במצב של סכנת חיים ממשית לכוח נמצא סביר במקרים אחרים.'}, {'q': 'במפעל התפוצץ דוד לחץ ופגע בעובר אורח ברחוב. אף אחד לא יודע מה גרם לפיצוץ, גם אחרי בדיקות מומחים. הדוד בשליטה מלאה של המפעל, ופיצוצים כאלה נובעים בדרך כלל מתחזוקה לקויה. מה הדין?', 'o': ['ס׳ 41 חל. נטל השכנוע עובר למפעל, שיצטרך להוכיח שלא התרשל', 'התובע חייב להוכיח בדיוק מה גרם לפיצוץ', 'חלה אחריות מוחלטת בלי הגנות', 'המפעל פטור כי הסיבה לא ידועה'], 'c': 0, 'e': 'נכון. שלושת התנאים מתקיימים: הנסיבות לא התבררו, יש שליטה מלאה, ויש הסתברות כללית לרשלנות. לפי נוימן עובר נטל השכנוע.'}, {'q': 'אש שהודלקה בשטח של חקלאי לשריפת גזם התפשטה לשדה השכן ושרפה את יבולו. השכן לא יודע איך האש התפשטה. מה הדין?', 'o': ['השכן חייב להוכיח רשלנות כרגיל', 'החקלאי פטור כי שריפת גזם מותרת', 'ס׳ 40 חל, כי מדובר בנזק לחקלאות', 'לפי ס׳ 39, החקלאי שהבעיר את האש צריך להוכיח שלא התרשל לגבי מקורה או התפשטותה'], 'c': 3, 'e': 'נכון. ס׳ 39 מעביר את הנטל למי שהבעיר את האש או אחראי להבערתה, ולתופש המקרקעין שממנו יצאה.'}, {'q': 'אדם נפגע מתריס שבור שנפל מחלון של בניין. הוא טוען שחלה חזקת "הדבר המסוכן" לפי ס׳ 38. מה הדין?', 'o': ['החזקה חלה תמיד על חלקי בניין', 'החזקה חלה רק אם התריס היה חדש', 'החזקה חלה, כי התריס גרם נזק', 'החזקה לא חלה כ"דבר מסוכן", כי "דבר מסוכן" הוא דבר שמסוכן מטבעו, כמו נשק, ולא חפץ שהתקלקל. אבל ייתכן שיחול ס׳ 41'], 'c': 3, 'e': 'נכון. הפסיקה פירשה "דבר מסוכן" כדבר שמסוכן מטבעו בשימוש הרגיל. תריס שבור יכול להיכנס לחזקה של ס׳ 41 אם תנאיו מתקיימים.'}, {'q': 'בית חולים לא תיעד שלב קריטי בלידה. בגלל זה אי אפשר לקבוע אם הצוות פעל כראוי. מה ההשלכה?', 'o': ['בית החולים חב באופן מוחלט', 'לחוסר הרישום אין משמעות משפטית', 'התובעים מפסידים, כי לא הוכיחו רשלנות', 'חזקת הנזק הראייתי יכולה להעביר לבית החולים את נטל השכנוע בשאלה שנפגעה, לפי היקף החסר הראייתי'], 'c': 3, 'e': 'נכון. לפי שטרנברג עובר נטל השכנוע, והיקף ההעברה נגזר מהיקף החסר.'}, {'q': 'מה קבעה הלכת שטרנברג לגבי תנאי "אי־הידיעה" בס׳ 41?', 'o': ['שתובע שמציג גרסה בכתב התביעה מאבד את הזכות להיעזר בחזקה', 'שהתנאי בוטל', 'שבוחנים אם נסיבות המקרה התבררו עד תום המשפט', 'שנבחנת רק ידיעת התובע ביום האירוע'], 'c': 2, 'e': 'נכון. הגיון הכלל הוא לפתור מצבים שבהם העובדות לא ידועות לבית המשפט, ולכן המועד הקובע הוא שלב ההכרעה.'}, {'q': 'מה הודגש בע״א 4486/11 פלוני נ׳ פלוני (2013) לגבי בחינת ההתרשלות?', 'o': ['שיש לבחון לפי מה שהיה ידוע בעת המעשה ולהתחשב בצורך להחליט מהר. בחירה בחלופה שבבחינה רגועה לא הייתה נבחרת אינה מוכיחה כשלעצמה התרשלות', 'שרופאים פטורים מאחריות בחירום', 'שיש לבחון את ההתנהגות בדיעבד, לאור התוצאה', 'שנוסחת הנד חלה רק על יעילות כלכלית'], 'c': 0, 'e': 'נכון. זה עיקרון "זמן אמת" בבחינת ההתרשלות.'}, {'q': 'מה עמד בלב ההכרעה בעניין גרובנר נ׳ עיריית חיפה?', 'o': ['שאין לעיריות חובת זהירות', 'שהעירייה התרשלה כי לא אכפה את האיסור', 'שעלות אכיפה מלאה בגנים גבוהה מאוד ביחס לסיכון, ולגנים הפתוחים יש ערך חברתי, ולכן לא נמצאה התרשלות', 'שרוכב האופניים פטור'], 'c': 2, 'e': 'נכון. ביהמ״ש איזן בין עלות המניעה, הסיכון והערך החברתי, וקבע שפיקוח חלקי הוא האיזון הראוי.'}, {'q': 'לפי לשון ס׳ 35, איזה סטנדרט חל על בעל מקצוע?', 'o': ['היכולת האישית של בעל המקצוע הנתבע', 'המיומנות והזהירות שאדם סביר ונבון וכשיר לפעול באותו משלח יד היה משתמש או נוקט באותן נסיבות', 'הרמה הגבוהה ביותר בעולם באותו תחום', 'רמת האדם הממוצע ברחוב'], 'c': 1, 'e': 'נכון. זה החלק השלישי של רישת ס׳ 35, והוא מבסס את הסטנדרט של בעל מקצוע סביר.'}, {'q': 'לפי לשון ס׳ 41, איזה תנאי נדרש לגבי הנכס שגרם לנזק?', 'o': ['שהנכס נמלט מהמקרקעין', 'שלנתבע הייתה שליטה מלאה על הנכס', 'שהנכס יהיה בבעלות המדינה', 'שהנכס יהיה מסוכן מטבעו'], 'c': 1, 'e': 'נכון. דרישת "שליטה מלאה" מצדיקה את העברת הנטל, כי לנתבע יש עדיפות במידע. השליטה לא חייבת להיות רצופה.'}, {'q': 'סטנדרט ההתרשלות הוא:', 'o': ['מה שהמזיק חשב', 'האדם הסביר והנבון (אובייקטיבי)', 'כוונת המזיק', 'רצון הניזוק'], 'c': 1, 'e': "ס' 35 — מבחן אובייקטיבי."}, {'q': 'בעל מקצוע נמדד לפי:', 'o': ['אדם רגיל', 'בעל מקצוע סביר וכשיר', 'עצמו', 'הניזוק'], 'c': 1, 'e': 'רמת זהירות מותאמת למומחיות.'}, {'q': 'נוסחת הנד מאזנת:', 'o': ['חובה מול נזק', 'עלות מניעה מול תוחלת הנזק', 'מזיק מול ניזוק', 'כוונה מול רשלנות'], 'c': 1, 'e': 'B < P·L.'}, {'q': 'מה עושה ס\' 41 ("הדבר מדבר בעדו")?', 'o': ['פוטר', 'מעביר את נטל ההוכחה לנתבע', 'קובע פיצוי', 'מבטל חובה'], 'c': 1, 'e': 'res ipsa loquitur.'}, {'q': 'אם עלות אמצעי מניעה זול נמוכה מתוחלת נזק גדול:', 'o': ['אין התרשלות', 'אי-נקיטתו היא התרשלות', 'פטור', 'אשם תורם'], 'c': 1, 'e': 'היה ראוי לנקוט אותו.'}]
